using System;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Windows.Forms;
namespace Frociart.Tests {internal static class ForLoopUiTests {
 static int checks;const BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
 static T Field<T>(object o,string name){return (T)o.GetType().GetField(name,Flags).GetValue(o);}
 static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,Flags).Invoke(o,args);}
 static void Check(bool b,string why){checks++;if(!b)throw new Exception(why);Console.WriteLine("PASS "+why);}
 static void Until(Func<bool> test,string why){var until=DateTime.UtcNow.AddSeconds(6);while(!test()&&DateTime.UtcNow<until){Application.DoEvents();Thread.Sleep(4);}Check(test(),why);}
 [STAThread] static int Main(){try{Application.EnableVisualStyles();using(var f=new MainForm(null,true)){f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-3000,-3000);f.Size=new Size(1420,900);bool shown=false;f.Shown+=(sender,e)=>shown=true;f.Show();Until(()=>shown,"Startup has completed before opening editor");f.EnterEditor();f.SetWorkspaceLayout(1,false);var doc=FlowPseudocode.Decode("p=2\nPER i DA 1 A 5 PASSO p FAI\nSTAMPA i\nFINE PER");f.SetDocument(doc,null,false);var preview=Field<PseudocodePreview>(f,"livePseudocode");Until(()=>preview.Code.Text.Contains("PER i DA 1 A 5 PASSO p FAI"),"Live panel displays readable dynamic FOR");
 var guard=doc.Nodes.Single(n=>n.Kind==NodeKind.Decision);f.Canvas.SelectNode(guard.Id);Application.DoEvents();var edit=Field<TextBox>(f,"expression");edit.Text="i < limite_ciclo_1";Until(()=>preview.Code.Text.Contains("MENTRE i < limite_ciclo_1"),"Draft changing condition reveals actual WHILE");Check(guard.Text.Contains("passo_ciclo_1"),"Preview preserves uncommitted source");f.CommitInspector();Until(()=>preview.Code.Text.Contains("MENTRE i < limite_ciclo_1"),"Commit remains faithful");Call(f,"Undo");Until(()=>preview.Code.Text.Contains("PER i DA"),"Undo restores FOR");Call(f,"Redo");Until(()=>preview.Code.Text.Contains("MENTRE i <"),"Redo restores graph change");
 Diagram imported=null;using(var dialog=new PseudocodeDialog(f.Document,null,d=>imported=d,d=>{})){dialog.StartPosition=FormStartPosition.Manual;dialog.Location=new Point(-3000,-3000);dialog.Show();dialog.Editor.Text="p=3\nPER i DA 1 A 7 PASSO p FAI\nSTAMPA i\nFINE PER";dialog.CreateDiagram();Check(imported!=null,"Dialog imports dynamic FOR");dialog.Close();}f.SetDocument(imported,null,false);Until(()=>preview.Code.Text.Contains("PASSO p"),"Imported code updates live panel");for(int i=0;i<80&&(f.Runner==null||(f.Runner.State!=RuntimeState.Completed&&f.Runner.State!=RuntimeState.Error));i++)f.SingleStep();Check(f.Runner.State==RuntimeState.Completed,"Actual window executes imported FOR");Check(String.Join("|",f.Runner.Output)=="1|4|7","Actual window output oracle");
 foreach(bool dark in new[]{true,false}){Ui.SetDarkMode(dark,false);Ui.ApplyTheme(f);Application.DoEvents();using(var shot=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(shot,new Rectangle(Point.Empty,f.Size));shot.Save(Path.Combine(Environment.GetEnvironmentVariable("FOR_QA"),"live-for-"+(dark?"dark":"light")+".png"));}Check(preview.Code.Width>=250&&preview.Code.Height>=100,"Readable preview area");}
 f.SetDocument(new Diagram(),null,false);f.Close();}Console.WriteLine("FOR_UI PASS checks="+checks);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}}
